-- M3 contract DDL v1. Cross-owner UUIDs are references, never foreign keys.
SET LOCAL timezone = 'UTC';
CREATE TABLE intake.tickets (id uuid PRIMARY KEY, version bigint NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), number text NOT NULL UNIQUE, service_id uuid NOT NULL, form_version integer NOT NULL CHECK(form_version>0), policy_version integer NOT NULL CHECK(policy_version>0), requester_kind text NOT NULL CHECK(requester_kind IN ('GUEST','PUBLIC','ASN')), requester_id uuid NOT NULL, requester_org_id uuid, service_owner_org_id uuid NOT NULL, handling_team_id uuid, assignee_id uuid, state text NOT NULL CHECK(state IN ('OPEN','TRIAGED','NEEDS_INFORMATION','ASSIGNED','IN_PROGRESS','RESOLVED','CLOSED','CANCELLED')), verification text NOT NULL DEFAULT 'PENDING' CHECK(verification IN ('PENDING','VERIFIED')), title text NOT NULL CHECK(length(title) BETWEEN 1 AND 200), description text NOT NULL CHECK(length(description) BETWEEN 1 AND 4000), accepted_at timestamptz NOT NULL, active_attempt_id uuid, episode_id uuid NOT NULL, archived_at timestamptz, CHECK(state NOT IN ('TRIAGED','ASSIGNED','IN_PROGRESS','RESOLVED','CLOSED') OR verification='VERIFIED'), CHECK(state NOT IN ('RESOLVED','CLOSED') OR active_attempt_id IS NOT NULL), CHECK(requester_kind<>'ASN' OR requester_org_id IS NOT NULL));
GRANT SELECT, INSERT, UPDATE ON intake.tickets TO helpdesk_m3;
CREATE TABLE intake.ticket_versions (id uuid PRIMARY KEY, version bigint NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), ticket_id uuid NOT NULL REFERENCES intake.tickets(id), ticket_version bigint NOT NULL CHECK(ticket_version>0), actor_id uuid NOT NULL, action text NOT NULL, reason text NOT NULL, public_summary text NOT NULL, correlation_id uuid NOT NULL, UNIQUE(ticket_id,ticket_version));
GRANT SELECT, INSERT ON intake.ticket_versions TO helpdesk_m3;
CREATE TABLE intake.comments (id uuid PRIMARY KEY, version bigint NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), ticket_id uuid NOT NULL REFERENCES intake.tickets(id), author_id uuid NOT NULL, visibility text NOT NULL CHECK(visibility IN ('REQUESTER','INTERNAL')), body text NOT NULL CHECK(length(body) BETWEEN 1 AND 4000));
GRANT SELECT, INSERT ON intake.comments TO helpdesk_m3;
CREATE TABLE intake.attachments (id uuid PRIMARY KEY, version bigint NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), ticket_id uuid REFERENCES intake.tickets(id), principal_id uuid NOT NULL, storage_key text NOT NULL UNIQUE, status text NOT NULL CHECK(status IN ('PENDING','QUARANTINED','CLEAN','REJECTED','MISSING')), visibility text NOT NULL DEFAULT 'PRIVATE' CHECK(visibility='PRIVATE'), mime text NOT NULL CHECK(mime IN ('image/png','image/jpeg','application/pdf')), size_bytes bigint NOT NULL CHECK(size_bytes BETWEEN 1 AND 10485760), sha256 bytea NOT NULL CHECK(octet_length(sha256)=32), alt text NOT NULL, license text NOT NULL, provenance_id uuid);
GRANT SELECT, INSERT, UPDATE ON intake.attachments TO helpdesk_m3;
CREATE TABLE intake.guest_capabilities (id uuid PRIMARY KEY, version bigint NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), ticket_id uuid NOT NULL REFERENCES intake.tickets(id), capability_hash bytea NOT NULL UNIQUE CHECK(octet_length(capability_hash)=32), scopes text[] NOT NULL, expires_at timestamptz NOT NULL, revoked_at timestamptz);
GRANT SELECT, INSERT, UPDATE ON intake.guest_capabilities TO helpdesk_m3;
CREATE TABLE intake.ticket_verifications (id uuid PRIMARY KEY, version bigint NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), ticket_id uuid NOT NULL REFERENCES intake.tickets(id), verified_by uuid NOT NULL, proposed_category uuid, confirmed_category uuid NOT NULL, confidence numeric CHECK(confidence BETWEEN 0 AND 1), classifier_version integer NOT NULL CHECK(classifier_version>0), explanation text NOT NULL, override_reason text NOT NULL, evidence_digest bytea NOT NULL CHECK(octet_length(evidence_digest)=32));
GRANT SELECT, INSERT ON intake.ticket_verifications TO helpdesk_m3;
CREATE TABLE intake.resolution_attempts (id uuid PRIMARY KEY, version bigint NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), ticket_id uuid NOT NULL REFERENCES intake.tickets(id), episode_id uuid NOT NULL, resolved_by uuid NOT NULL, summary text NOT NULL, resolved_at timestamptz NOT NULL, confirmation_due_at timestamptz NOT NULL, outcome text NOT NULL CHECK(outcome IN ('PENDING','REVIEW_REQUIRED','ACCEPTED','REJECTED','AUTO_NO_RESPONSE')), CHECK(confirmation_due_at=resolved_at+interval '24 hours'), UNIQUE(ticket_id,id));
GRANT SELECT, INSERT, UPDATE ON intake.resolution_attempts TO helpdesk_m3;
CREATE TABLE intake.confirmation_events (id uuid PRIMARY KEY, version bigint NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), ticket_id uuid NOT NULL, attempt_id uuid NOT NULL, actor_id uuid NOT NULL, decision text NOT NULL CHECK(decision IN ('ACCEPT','REJECT','FEEDBACK','AUTO_NO_RESPONSE')), FOREIGN KEY(ticket_id,attempt_id) REFERENCES intake.resolution_attempts(ticket_id,id));
GRANT SELECT, INSERT ON intake.confirmation_events TO helpdesk_m3;
CREATE TABLE intake.confirmation_notifications (id uuid PRIMARY KEY, version bigint NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), ticket_id uuid NOT NULL, attempt_id uuid NOT NULL, notification_id uuid NOT NULL UNIQUE, event_id uuid NOT NULL UNIQUE, stored_at timestamptz NOT NULL, FOREIGN KEY(ticket_id,attempt_id) REFERENCES intake.resolution_attempts(ticket_id,id), UNIQUE(ticket_id,attempt_id,notification_id));
GRANT SELECT, INSERT ON intake.confirmation_notifications TO helpdesk_m3;
CREATE TABLE intake.work_logs (id uuid PRIMARY KEY, version bigint NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), ticket_id uuid NOT NULL REFERENCES intake.tickets(id), actor_id uuid NOT NULL, started_at timestamptz NOT NULL, ended_at timestamptz NOT NULL, summary text NOT NULL, CHECK(ended_at>=started_at));
GRANT SELECT, INSERT ON intake.work_logs TO helpdesk_m3;
CREATE TABLE intake.vendor_cases (id uuid PRIMARY KEY, version bigint NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), ticket_id uuid NOT NULL REFERENCES intake.tickets(id), vendor_id uuid NOT NULL, internal_pic_id uuid NOT NULL, external_reference text NOT NULL, contract_reference text NOT NULL, evidence_ids uuid[] NOT NULL, acknowledged_at timestamptz, expected_return_at timestamptz NOT NULL, next_followup_at timestamptz NOT NULL);
GRANT SELECT, INSERT, UPDATE ON intake.vendor_cases TO helpdesk_m3;
CREATE TABLE intake.handoff_requests (id uuid PRIMARY KEY, version bigint NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), ticket_id uuid NOT NULL REFERENCES intake.tickets(id), from_org_id uuid NOT NULL, target_org_id uuid NOT NULL, target_team_id uuid NOT NULL, requested_by uuid NOT NULL, accepted_by uuid, accepted_at timestamptz, reason text NOT NULL, state text NOT NULL CHECK(state IN ('PENDING','ACCEPTED','REJECTED')), CHECK(from_org_id<>target_org_id), CHECK((state='ACCEPTED')=(accepted_at IS NOT NULL AND accepted_by IS NOT NULL)));
GRANT SELECT, INSERT, UPDATE ON intake.handoff_requests TO helpdesk_m3;
CREATE TABLE intake.pause_intervals (id uuid PRIMARY KEY, version bigint NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), ticket_id uuid NOT NULL REFERENCES intake.tickets(id), starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, approved_by uuid NOT NULL, policy_version integer NOT NULL CHECK(policy_version>0), reason text NOT NULL, CHECK(ends_at>starts_at));
GRANT SELECT, INSERT, UPDATE ON intake.pause_intervals TO helpdesk_m3;
CREATE TABLE intake.drafts (id uuid PRIMARY KEY, version bigint NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), principal_id uuid NOT NULL, form_version integer NOT NULL CHECK(form_version>0), title text NOT NULL, description text NOT NULL, expires_at timestamptz NOT NULL);
GRANT SELECT, INSERT, UPDATE ON intake.drafts TO helpdesk_m3;
CREATE TABLE intake.draft_attachment_refs (id uuid PRIMARY KEY, version bigint NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), draft_id uuid NOT NULL REFERENCES intake.drafts(id), attachment_id uuid NOT NULL REFERENCES intake.attachments(id), UNIQUE(draft_id,attachment_id));
GRANT SELECT, INSERT, UPDATE ON intake.draft_attachment_refs TO helpdesk_m3;
CREATE TABLE intake.escalation_marks (id uuid PRIMARY KEY, version bigint NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), ticket_id uuid NOT NULL REFERENCES intake.tickets(id), episode_id uuid NOT NULL, level text NOT NULL CHECK(level IN ('L2','COORDINATOR','LEADERSHIP')), rule_version integer NOT NULL CHECK(rule_version>0), reason text NOT NULL);
GRANT SELECT, INSERT ON intake.escalation_marks TO helpdesk_m3;
CREATE TABLE intake.operations (id uuid PRIMARY KEY, version bigint NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), ticket_id uuid NOT NULL REFERENCES intake.tickets(id), principal_id uuid NOT NULL, kind text NOT NULL CHECK(kind='ESCALATE'), state text NOT NULL CHECK(state IN ('PENDING','RUNNING','SUCCEEDED','FAILED')), reason text NOT NULL);
GRANT SELECT, INSERT, UPDATE ON intake.operations TO helpdesk_m3;
CREATE TABLE intake.idempotency_records (actor_scope text NOT NULL, command text NOT NULL, target text NOT NULL, key text NOT NULL CHECK(length(key) BETWEEN 16 AND 128), payload_digest bytea NOT NULL CHECK(octet_length(payload_digest)=32), response_status integer NOT NULL CHECK(response_status BETWEEN 200 AND 299), response_body jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, PRIMARY KEY(actor_scope,command,target,key));
CREATE TABLE intake.outbox (event_id uuid PRIMARY KEY, event_type text NOT NULL, schema_version integer NOT NULL CHECK(schema_version>0), aggregate_id uuid NOT NULL, aggregate_version bigint NOT NULL CHECK(aggregate_version>0), occurred_at timestamptz NOT NULL, correlation_id uuid NOT NULL, payload jsonb NOT NULL CHECK(jsonb_typeof(payload)='object'), digest bytea NOT NULL CHECK(octet_length(digest)=32));
CREATE TABLE intake.outbox_delivery (event_id uuid NOT NULL REFERENCES intake.outbox(event_id), consumer_id text NOT NULL CHECK(consumer_id ~ '^M[1-9]$'), state text NOT NULL CHECK(state IN ('PENDING','LEASED','ACKED','DEAD_LETTER')), attempts integer NOT NULL DEFAULT 0 CHECK(attempts>=0), lease_until timestamptz, acked_at timestamptz, last_error_code text, PRIMARY KEY(event_id,consumer_id), CHECK((state='ACKED')=(acked_at IS NOT NULL)));
CREATE TABLE intake.inbox (consumer_id text NOT NULL, event_id uuid NOT NULL, digest bytea NOT NULL CHECK(octet_length(digest)=32), aggregate_id uuid NOT NULL, aggregate_version bigint NOT NULL CHECK(aggregate_version>0), received_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(consumer_id,event_id));
CREATE TABLE intake.audit_intents (id uuid PRIMARY KEY, actor_id uuid NOT NULL, action text NOT NULL, object_id uuid NOT NULL, scope text NOT NULL, reason text NOT NULL, outcome text NOT NULL, correlation_id uuid NOT NULL, occurred_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON intake.idempotency_records, intake.outbox, intake.inbox, intake.audit_intents TO helpdesk_m3;
GRANT SELECT, INSERT, UPDATE ON intake.outbox_delivery TO helpdesk_m3;
CREATE INDEX ON intake.outbox_delivery (state, lease_until, event_id) WHERE state<>'ACKED';
ALTER TABLE intake.tickets ADD CONSTRAINT active_attempt_owner FOREIGN KEY(id,active_attempt_id) REFERENCES intake.resolution_attempts(ticket_id,id) DEFERRABLE INITIALLY DEFERRED;
CREATE INDEX ON intake.tickets (requester_id, updated_at DESC, id DESC);
CREATE INDEX ON intake.tickets (service_owner_org_id, state, updated_at DESC, id DESC);
CREATE INDEX ON intake.comments (ticket_id, visibility, created_at, id);
CREATE INDEX ON intake.drafts (principal_id, updated_at DESC, id DESC);
REVOKE ALL ON ALL TABLES IN SCHEMA intake FROM PUBLIC;
